bounded_host_request.command:
set -eu
python3 -B - <<'PY'
import subprocess,json,sys
def run(*args):
 return subprocess.run(args,capture_output=True,text=True)
p=run("docker","ps","--format","{{json .}}")
if p.returncode:sys.exit(80)
cs=[json.loads(x) for x in p.stdout.splitlines() if x.strip()]
bots=[c for c in cs if "gaybbs" in (c.get("Names","").lower())]
dbs=[c for c in cs if "postgres" in (c.get("Names","").lower())]
if len(bots)!=1:sys.exit(81)
bot=bots[0]["Names"]
details=run("docker","inspect",bot)
if details.returncode:sys.exit(82)
j=json.loads(details.stdout)[0]
env={x.split("=",1)[0]:x.split("=",1)[1] for x in j["Config"].get("Env",[]) if "=" in x}
names={m["Destination"] for m in j.get("Mounts",[])}
print("BOT_RUNNING=YES")
print("USERBOT_ACCOUNT_ENV="+str("GAYBBS_USERBOT_ACCOUNT_CHAT_ID_FILE" in env))
print("OPER_RECIPIENT_ENV="+str("GAYBBS_USERBOT_REPORT_CHAT_ID_FILE" in env))
print("REPORT_ACCOUNT_SECRET_MOUNT="+str("/run/secrets/bug_report_userbot_account" in names))
print("REPORT_OPERATOR_SECRET_MOUNT="+str("/run/secrets/bug_report_recipient" in names))
if len(dbs)!=1:sys.exit(83)
q=run("docker","exec",dbs[0]["Names"],"psql","-U","gace","-d","gaybbs","-tA","-c","SELECT state,COUNT(*) FROM gaybbs_bug_reports GROUP BY state ORDER BY state;")
if q.returncode:sys.exit(84)
for line in q.stdout.splitlines():
 if "|" not in line:continue
 state,count=line.split("|",1)
 if state in {"pending","forwarding","delivered","queued","uncertain","cancelled"} and count.isdecimal():
  print("REPORT_STATE_"+state+"="+count)
q=run("docker","exec",dbs[0]["Names"],"psql","-U","gace","-d","gaybbs","-tA","-c","SELECT COUNT(*) FROM information_schema.tables WHERE table_schema='public' AND table_name='gaybbs_bug_report_userbot_delivery';")
print("USERBOT_DELIVERY_TABLE="+(q.stdout.strip() if q.returncode==0 else "QUERY_FAILED"))
PY
